struct Params {
  amount: f32, // @default 1  Master level of the bounce.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;
@group(0) @binding(5) var inputTexture2: texture_2d<f32>;

fn at(tex: texture_2d<f32>, p: vec2i) -> vec4f {
  let size = vec2i(textureDimensions(tex));
  return textureLoad(tex, clamp(p, vec2i(0), size - vec2i(1)), 0);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let lit = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let size = vec2f(textureDimensions(inputTexture1));
  let g = uv * size - 0.5;
  let b = vec2i(floor(g));
  let f = fract(g);
  let gi = mix(mix(at(inputTexture1, b), at(inputTexture1, b + vec2i(1, 0)), f.x), mix(at(inputTexture1, b + vec2i(0, 1)), at(inputTexture1, b + vec2i(1, 1)), f.x), f.y).rgb;
  let base = at(inputTexture2, vec2i(uv * vec2f(textureDimensions(inputTexture2))));
  let diffuse = base.rgb * (1.0 - base.a * 0.7);
  return vec4f(lit.rgb + diffuse * gi * params.amount, lit.a);
}

struct Params {
  threshold: f32, // @default 1.2  Linear radiance where bloom starts.
  knee: f32, // @default 0.8  Softness of the threshold.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let color = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).rgb;
  let brightness = max(color.r, max(color.g, color.b));
  let soft = clamp(brightness - params.threshold + params.knee, 0.0, 2.0 * params.knee);
  let weight = max(soft * soft / (4.0 * params.knee + 1e-4), brightness - params.threshold) / max(brightness, 1e-4);
  return vec4f(color * weight, 1.0);
}

struct Params {
  windows: f32, // @default 1.4  Radiance of the side-window bands.
  skylights: f32, // @default 0.9  Radiance of the roof skylights.
  roof: f32, // @default 0.012  Radiance of the dark roof.
  floorBounce: f32, // @default 0.035  Warm light bounced off the floor.
  sun: f32, // @default 6  Radiance of the sun seen through the windows.
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

const SUN_DIRECTION: vec3f = vec3f(-0.3004, 0.8511, 0.4306);

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  // Keep the input bound (the node requires one); its value never reaches the picture.
  let unused = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).a * 0.0;
  let phi = (uv.x - 0.5) * 6.2831853;
  let theta = uv.y * 3.1415927;
  let d = vec3f(sin(theta) * sin(phi), cos(theta), -sin(theta) * cos(phi));
  var radiance = mix(vec3f(0.035, 0.026, 0.018) * params.floorBounce / 0.035, vec3f(0.62, 0.64, 0.68) * params.roof, smoothstep(-0.2, 0.3, d.y));
  // Side windows: horizontal bands facing ±Z, between low and high elevation, mullioned.
  let side = abs(d.z);
  let band = smoothstep(0.05, 0.12, d.y) * (1.0 - smoothstep(0.32, 0.42, d.y)) * smoothstep(0.55, 0.8, side);
  let mullions = step(0.18, fract(atan2(d.x, side) * 7.0));
  radiance = radiance + vec3f(0.7, 0.88, 1.0) * params.windows * band * mullions;
  // Skylights: a strip along the roof ridge (X).
  let ridge = smoothstep(0.85, 0.97, d.y) * (1.0 - smoothstep(0.08, 0.2, abs(d.z)));
  radiance = radiance + vec3f(0.68, 0.86, 1.0) * params.skylights * ridge * step(0.4, fract(d.x * 3.0));
  // The sun, low, seen through the window side.
  radiance = radiance + vec3f(1.0, 0.9, 0.75) * params.sun * pow(max(dot(d, SUN_DIRECTION), 0.0), 900.0);
  return vec4f(radiance + vec3f(unused), 1.0);
}

struct Params {
  eye: vec3f, // @default 0  Camera position (drive from the camera).
  aim: vec3f, // @default 0  Camera look-at (drive from the camera).
  fov: f32, // @default 50  Camera vertical field of view, degrees.
  far: f32, // @default 400  Camera far plane (depth arrives as distance ÷ far).
  roll: f32, // @default 0  Camera roll, degrees (drive from the camera).
  radius: f32, // @default 6  Gather radius, metres.
  strength: f32, // @default 1  Bounce strength.
};
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
