// T1354b — the machine rig (generated by src/projects/furnace/rig-kernel.ts from the GLB).
// Each vertex's part is surface.w; its motion applies about the part's REST pivot, then its
// parent's, child first. Stateless: the rest pose is read from upstream every frame.
struct Params {
  shellTilt: f32, // @default 0  Furnace shell tilt about the rocker, radians (+ tips toward the tap).
  roofLift: f32, // @default 0  Roof lift, metres.
  roofSwing: f32, // @default 0  Roof swing about its column, radians.
  electrode1: f32, // @default 0  Electrode 1 travel, metres (negative = down into the bath).
  electrode2: f32, // @default 0  Electrode 2 travel, metres.
  electrode3: f32, // @default 0  Electrode 3 travel, metres.
  craneX: f32, // @default 0  Scrap crane bridge travel along the bay, metres.
  trolley: f32, // @default 0  Scrap crane trolley travel across the bridge, metres.
  hook: f32, // @default 0  Scrap crane hook height, metres (negative lowers).
  bucketSway: f32, // @default 0  Scrap bucket sway on the hook, radians.
  bucketOpen: f32, // @default 0  Clamshell jaw opening, radians.
  crane2X: f32, // @default 0  Ladle crane bridge travel, metres.
  trolley2: f32, // @default 0  Ladle crane trolley travel, metres.
  hook2: f32, // @default 0  Ladle crane hook height, metres.
  ladleCar: f32, // @default 0  Ladle transfer car travel on its rails, metres.
  ladleTilt: f32, // @default 0  Ladle pour tilt about the trunnions, radians.
  slagTilt: f32, // @default 0  Slag pot tilt, radians.
  turret: f32, // @default 0  Ladle turret rotation, radians.
  casting: f32, // @default 0  Caster strand travel (uv scroll), metres.
  conveyor: f32, // @default 0  Conveyor belt travel (uv scroll), metres.
};

const RIG_PARTS: u32 = 29u;
const RIG_PARENT = array<u32, 29>(0u, 0u, 1u, 1u, 1u, 1u, 0u, 0u, 7u, 8u, 9u, 10u, 10u, 8u, 0u, 14u, 15u, 15u, 0u, 18u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u);
const RIG_PIVOT = array<vec3f, 29>(vec3f(0.0), vec3f(0.0000, 10.8000, 0.0000), vec3f(-0.5889, 9.4500, 0.3400), vec3f(0.0000, 9.4500, -0.6800), vec3f(0.5889, 9.4500, 0.3400), vec3f(4.4000, 12.5600, -5.9000), vec3f(0.0), vec3f(-10.5000, 24.0000, 0.0000), vec3f(-10.5000, 26.6500, 4.2000), vec3f(-10.5000, 21.0000, 4.2000), vec3f(-10.5000, 19.5500, 4.2000), vec3f(-8.2500, 14.4500, 4.2000), vec3f(-12.7500, 14.4500, 4.2000), vec3f(-10.5000, 28.4500, 4.2000), vec3f(27.0000, 24.0000, 0.0000), vec3f(27.0000, 26.6500, -2.5000), vec3f(27.0000, 19.5000, -2.5000), vec3f(27.0000, 28.4500, -2.5000), vec3f(16.0000, 0.0000, 0.0000), vec3f(16.0000, 4.1200, 0.0000), vec3f(-8.3000, 2.4940, 0.0000), vec3f(38.0000, 12.0000, 0.4000), vec3f(38.1067, 9.5803, 6.0000), vec3f(38.9875, 6.7825, 6.0000), vec3f(40.7798, 4.2852, 6.0000), vec3f(43.1908, 2.5335, 6.0000), vec3f(45.9827, 1.6219, 6.0000), vec3f(38.0000, 11.0000, 6.0000), vec3f(-46.0000, 1.6000, 11.0000));

fn axisAngle(axis: vec3f, angle: f32) -> mat3x3f {
  let c = cos(angle);
  let s = sin(angle);
  let t = 1.0 - c;
  let a = normalize(axis);
  return mat3x3f(
    vec3f(t * a.x * a.x + c, t * a.x * a.y + s * a.z, t * a.x * a.z - s * a.y),
    vec3f(t * a.x * a.y - s * a.z, t * a.y * a.y + c, t * a.y * a.z + s * a.x),
    vec3f(t * a.x * a.z + s * a.y, t * a.y * a.z - s * a.x, t * a.z * a.z + c),
  );
}

fn moveOne(part: u32, p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let pivot = RIG_PIVOT[part];
  switch part {
    case 1u: { let r = axisAngle(vec3f(0.0, 0.0, 1.0), ctx.params.shellTilt); q.position = pivot + r * (q.position - pivot); q.normal = r * q.normal; }
    case 5u: { let r = axisAngle(vec3f(0.0, 1.0, 0.0), ctx.params.roofSwing); q.position = pivot + r * (q.position - pivot) + vec3f(0.0, ctx.params.roofLift, 0.0); q.normal = r * q.normal; }
    case 2u: { q.position = q.position + vec3f(0.0, 1.0, 0.0) * ctx.params.electrode1; }
    case 3u: { q.position = q.position + vec3f(0.0, 1.0, 0.0) * ctx.params.electrode2; }
    case 4u: { q.position = q.position + vec3f(0.0, 1.0, 0.0) * ctx.params.electrode3; }
    case 7u: { q.position = q.position + vec3f(1.0, 0.0, 0.0) * ctx.params.craneX; }
    case 8u: { q.position = q.position + vec3f(0.0, 0.0, -1.0) * ctx.params.trolley; }
    case 9u: { q.position = q.position + vec3f(0.0, 1.0, 0.0) * ctx.params.hook; }
    case 13u: { let stretch = max(0.01, (7.4500 - ctx.params.hook) / 7.4500); q.position.y = pivot.y + (q.position.y - pivot.y) * stretch; }
    case 10u: { let r = axisAngle(vec3f(0.0, 0.0, 1.0), ctx.params.bucketSway); q.position = pivot + r * (q.position - pivot); q.normal = r * q.normal; }
    case 11u: { let r = axisAngle(vec3f(0.0, 0.0, 1.0), ctx.params.bucketOpen); q.position = pivot + r * (q.position - pivot); q.normal = r * q.normal; }
    case 12u: { let r = axisAngle(vec3f(0.0, 0.0, -1.0), ctx.params.bucketOpen); q.position = pivot + r * (q.position - pivot); q.normal = r * q.normal; }
    case 14u: { q.position = q.position + vec3f(1.0, 0.0, 0.0) * ctx.params.crane2X; }
    case 15u: { q.position = q.position + vec3f(0.0, 0.0, -1.0) * ctx.params.trolley2; }
    case 16u: { q.position = q.position + vec3f(0.0, 1.0, 0.0) * ctx.params.hook2; }
    case 17u: { let stretch = max(0.01, (8.9500 - ctx.params.hook2) / 8.9500); q.position.y = pivot.y + (q.position.y - pivot.y) * stretch; }
    case 18u: { q.position = q.position + vec3f(1.0, 0.0, 0.0) * ctx.params.ladleCar; }
    case 19u: { let r = axisAngle(vec3f(0.0, 0.0, 1.0), ctx.params.ladleTilt); q.position = pivot + r * (q.position - pivot); q.normal = r * q.normal; }
    case 20u: { let r = axisAngle(vec3f(0.0, 0.0, 1.0), ctx.params.slagTilt); q.position = pivot + r * (q.position - pivot); q.normal = r * q.normal; }
    case 21u: { let r = axisAngle(vec3f(0.0, 1.0, 0.0), ctx.params.turret); q.position = pivot + r * (q.position - pivot); q.normal = r * q.normal; }
    case 22u: { q.uv.y = q.uv.y + ctx.params.casting; }
    case 23u: { q.uv.y = q.uv.y + ctx.params.casting; }
    case 24u: { q.uv.y = q.uv.y + ctx.params.casting; }
    case 25u: { q.uv.y = q.uv.y + ctx.params.casting; }
    case 26u: { q.uv.y = q.uv.y + ctx.params.casting; }
    case 27u: { q.uv.x = q.uv.x + ctx.params.casting; }
    case 28u: { q.uv.x = q.uv.x + ctx.params.conveyor; }
    default: {}
  }
  return q;
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  var part = u32(max(p.surface.w, 0.0) + 0.5);
  // Child first, then each ancestor — at most six levels (hook ← trolley ← bridge).
  for (var level = 0u; level < 6u; level = level + 1u) {
    if (part == 0u || part >= RIG_PARTS) { break; }
    q = moveOne(part, q, ctx);
    part = RIG_PARENT[part];
  }
  return q;
}

