struct Params {
  eye: vec3f, // @default 0  Camera position (drive from the camera).
  aim: vec3f, // @default 0  Camera look-at (drive from the camera).
  fov: f32, // @default 50  Camera vertical field of view, degrees.
  far: f32, // @default 400  Camera far plane.
  roll: f32, // @default 0  Camera roll, degrees.
  amount: f32, // @default 0  0 = off; 1 = the slab fully treated.
  mode: f32, // @default 0  0 wire, 1 mono, 2 thermal (fractional values blend neighbours).
  centre: f32, // @default 0  Slab centre along the hall (world X, metres).
  width: f32, // @default 12  Slab width, metres.
  edgeColour: vec3f, // @default 1  Colour of the wireframe lines and the slab's seam.
};

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;
@group(0) @binding(5) var inputTexture2: texture_2d<f32>;

fn rolledRight(forward: vec3f, rollDeg: f32) -> vec3f {
  var up = select(vec3f(0.0, 1.0, 0.0), vec3f(0.0, 0.0, 1.0), abs(forward.y) > 0.999);
  let t = radians(rollDeg);
  up = up * cos(t) + cross(forward, up) * sin(t) + forward * dot(forward, up) * (1.0 - cos(t));
  return normalize(cross(forward, up));
}

fn texelOf(tex: texture_2d<f32>, uv: vec2f) -> vec2i {
  let size = vec2f(textureDimensions(tex));
  return clamp(vec2i(uv * size), vec2i(0), vec2i(size) - vec2i(1));
}

fn depthAt(uv: vec2f) -> f32 {
  return textureLoad(inputTexture1, texelOf(inputTexture1, uv), 0).r;
}

fn normalAt(uv: vec2f) -> vec4f {
  return textureLoad(inputTexture2, texelOf(inputTexture2, uv), 0);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let colour = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  if (params.amount <= 0.001) { return colour; }
  let d = depthAt(uv);
  let surface = d > 0.0 && d < 0.9999;
  // World X of this pixel: the slab is chosen in the world, not on the screen.
  let forward = normalize(params.aim - params.eye);
  let right = rolledRight(forward, params.roll);
  let up = cross(right, forward);
  let tanHalf = tan(radians(params.fov) * 0.5);
  let aspect = frameU.resolution.x / max(frameU.resolution.y, 1.0);
  let ndc = vec2f(uv.x * 2.0 - 1.0, 1.0 - uv.y * 2.0);
  let ray = normalize(forward + right * ndc.x * tanHalf * aspect + up * ndc.y * tanHalf);
  let world = params.eye + ray * (select(0.5, d, surface) * params.far / max(dot(ray, forward), 1e-3));
  let offset = abs(world.x - params.centre);
  let inside = (1.0 - smoothstep(params.width * 0.5 - 0.4, params.width * 0.5, offset)) * params.amount;
  let seam = exp(-pow((offset - params.width * 0.5) / 0.15, 2.0)) * params.amount * select(0.0, 1.0, surface);
  if (inside <= 0.0 && seam <= 0.01) { return colour; }

  let luma = dot(colour.rgb, vec3f(0.2126, 0.7152, 0.0722));
  // WIRE: 1-pixel edges from normal and depth discontinuities, on black.
  let px = 1.0 / frameU.resolution;
  let n0 = normalAt(uv);
  let nx = normalAt(uv + vec2f(px.x, 0.0));
  let ny = normalAt(uv + vec2f(0.0, px.y));
  let crease = max(1.0 - dot(n0.rgb * 2.0 - 1.0, nx.rgb * 2.0 - 1.0), 1.0 - dot(n0.rgb * 2.0 - 1.0, ny.rgb * 2.0 - 1.0));
  let dx = abs(depthAt(uv + vec2f(px.x, 0.0)) - d);
  let dy = abs(depthAt(uv + vec2f(0.0, px.y)) - d);
  let silhouette = max(dx, dy) / max(d, 1e-4);
  let edge = clamp(smoothstep(0.08, 0.3, crease) + smoothstep(0.01, 0.04, silhouette), 0.0, 1.0);
  let hot = max(colour.r - max(colour.g, colour.b) * 0.6, 0.0);
  let wire = params.edgeColour * edge * 0.9 + colour.rgb * smoothstep(0.35, 0.8, luma) * 0.8 + vec3f(hot, hot * 0.3, 0.0) * 0.5;
  // MONO: steel grey, only the reds and oranges survive.
  let warmth = smoothstep(0.1, 0.35, colour.r - colour.b);
  let mono = mix(vec3f(luma * 0.9), colour.rgb * 1.1, warmth);
  // THERMAL: false colour from luminance — black, violet, red, orange, white.
  let t = clamp(pow(luma, 0.7), 0.0, 1.0);
  let thermal = mix(mix(mix(vec3f(0.0, 0.0, 0.05), vec3f(0.35, 0.0, 0.45), smoothstep(0.0, 0.25, t)), vec3f(0.9, 0.1, 0.05), smoothstep(0.25, 0.55, t)), mix(vec3f(1.0, 0.55, 0.0), vec3f(1.0, 1.0, 0.85), smoothstep(0.8, 1.0, t)), smoothstep(0.55, 0.8, t));
  let m = clamp(params.mode, 0.0, 2.0);
  let treated = select(mix(mono, thermal, m - 1.0), mix(wire, mono, m), m < 1.0);
  var out = mix(colour.rgb, treated, inside);
  out = out + params.edgeColour * seam * 0.6;
  return vec4f(out, colour.a);
}

struct Params {
  eye: vec3f, // @default 0  Camera position (drive from the camera).
  aim: vec3f, // @default 0  Camera look-at (drive from the camera).
  fov: f32, // @default 50  Camera vertical field of view, degrees.
  far: f32, // @default 400  Camera far plane (depth arrives as distance ÷ far).
  roll: f32, // @default 0  Camera roll, degrees (drive from the camera).
  prevEye: vec3f, // @default 0  The camera's position one frame ago.
  prevAim: vec3f, // @default 0  The camera's look-at one frame ago.
  prevFov: f32, // @default 50  The camera's fov one frame ago.
  prevRoll: f32, // @default 0  The camera's roll one frame ago, degrees.
  shutter: f32, // @default 0.35  Shutter as a share of the frame (0.5 = a 180° shutter).
};
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;

// T1383b: the camera's right vector with its ROLL — world up turned about the view axis by
// roll degrees (Rodrigues), exactly as camera.ts guardedRolledUp builds the render's view.
fn rolledRight(forward: vec3f, rollDeg: f32) -> vec3f {
  var up = select(vec3f(0.0, 1.0, 0.0), vec3f(0.0, 0.0, 1.0), abs(forward.y) > 0.999);
  let t = radians(rollDeg);
  up = up * cos(t) + cross(forward, up) * sin(t) + forward * dot(forward, up) * (1.0 - cos(t));
  return normalize(cross(forward, up));
}

struct View {
  forward: vec3f,
  right: vec3f,
  up: vec3f,
  tanHalf: f32,
  aspect: f32,
};

fn makeView() -> View {
  var v: View;
  v.forward = normalize(params.aim - params.eye);
  v.right = rolledRight(v.forward, params.roll);
  v.up = cross(v.right, v.forward);
  v.tanHalf = tan(radians(params.fov) * 0.5);
  v.aspect = frameU.resolution.x / max(frameU.resolution.y, 1.0);
  return v;
}

fn rayAt(v: View, uv: vec2f) -> vec3f {
  let ndc = vec2f(uv.x * 2.0 - 1.0, 1.0 - uv.y * 2.0);
  return normalize(v.forward + v.right * ndc.x * v.tanHalf * v.aspect + v.up * ndc.y * v.tanHalf);
}

fn depthTexel(uv: vec2f) -> vec2i {
  let size = vec2f(textureDimensions(inputTexture1));
  return clamp(vec2i(uv * size), vec2i(0), vec2i(size) - vec2i(1));
}

// View-plane distance at uv, or a negative number where there is no surface.
fn viewDepth(uv: vec2f) -> f32 {
  let d = textureLoad(inputTexture1, depthTexel(uv), 0).r;
  return select(d * params.far, -1.0, d >= 0.9999 || d <= 0.0);
}

fn worldAt(v: View, uv: vec2f, z: f32) -> vec3f {
  let ray = rayAt(v, uv);
  return params.eye + ray * (z / max(dot(ray, v.forward), 1e-4));
}

// World point → (uv, view-plane distance); z ≤ 0 means behind the camera.
fn project(v: View, world: vec3f) -> vec3f {
  let rel = world - params.eye;
  let z = dot(rel, v.forward);
  let x = dot(rel, v.right) / (max(z, 1e-4) * v.tanHalf * v.aspect);
  let y = dot(rel, v.up) / (max(z, 1e-4) * v.tanHalf);
  return vec3f(x * 0.5 + 0.5, 0.5 - y * 0.5, z);
}

fn ignHash(pixel: vec2f) -> f32 {
  return fract(52.9829189 * fract(dot(pixel, vec2f(0.06711056, 0.00583715))));
}

const SAMPLES: u32 = 16u;

fn projectWith(eye: vec3f, aim: vec3f, fov: f32, roll: f32, aspect: f32, world: vec3f) -> vec2f {
  let forward = normalize(aim - eye);
  let right = rolledRight(forward, roll);
  let up = cross(right, forward);
  let tanHalf = tan(radians(fov) * 0.5);
  let rel = world - eye;
  let z = max(dot(rel, forward), 1e-4);
  return vec2f(dot(rel, right) / (z * tanHalf * aspect) * 0.5 + 0.5, 0.5 - dot(rel, up) / (z * tanHalf) * 0.5);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let centre = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let v = makeView();
  var z = viewDepth(uv);
  if (z < 0.0) { z = params.far * 0.5; }
  let world = worldAt(v, uv, z);
  let previous = projectWith(params.prevEye, params.prevAim, params.prevFov, params.prevRoll, v.aspect, world);
  let velocity = (uv - previous) * params.shutter;
  if (length(velocity) > 0.25 || length(velocity * frameU.resolution) < 0.5) { return centre; }
  let jitter = ignHash(uv * frameU.resolution + vec2f(frameU.absFrame * 1.7)) - 0.5;
  var sum = vec3f(0.0);
  for (var i = 0u; i < SAMPLES; i = i + 1u) {
    let t = (f32(i) + 0.5 + jitter) / f32(SAMPLES) - 0.5;
    sum = sum + textureSampleLevel(inputTexture, inputSampler, uv + velocity * t, 0.0).rgb;
  }
  return vec4f(sum / f32(SAMPLES), centre.a);
}

struct Params {
  sky: f32, // @default 1  Base brightness of the sky in the openings (the director drives it).
  chase: f32, // @default 0  0..1: a bright band running along the hall through the windows (the build).
  strobe: f32, // @default 0  Snares: alternate windows blink hard.
  pick: f32, // @default 0  Running kick count: each kick flares a few windows, a new few each time.
  warm: f32, // @default 0  0..1: the daylight turns to sodium orange (the peaks).
};

fn skyHash(c: f32) -> f32 {
  return fract(sin(c * 91.345 + 7.13) * 43758.5453);
}

fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
  var o = surfaceDefaults(s);
  o.albedo = vec4f(0.0, 0.0, 0.0, 1.0);
  // One "window" is a 6 m bay along the hall (X) on either side (Z sign).
  let bay = floor(s.world.x / 6.0) + select(0.0, 100.0, s.world.z > 0.0);
  let chase = pow(0.5 + 0.5 * sin(s.world.x * 0.12 - s.absTime * 5.0), 6.0) * p.chase * 3.0;
  let strobe = p.strobe * step(0.5, fract(bay * 0.5)) * 2.5;
  let flare = step(0.82, skyHash(bay + p.pick * 13.0)) * 3.0 * step(0.5, p.pick);
  let level = p.sky + chase + strobe + flare;
  let tint = mix(vec3f(1.0), vec3f(1.6, 0.75, 0.3), p.warm);
  // Openings near the floor (the hall's doors to the yard) stay dim: at full sky brightness
  // they leaked white light under the machinery.
  // Old wired glass, not a light panel: a pane grid with dark mullions, soot and streaks
  // thickest at the bottom of each pane, and here and there a pane boarded or black.
  let a = abs(s.normal);
  let uv = select(select(s.world.xy, s.world.zy, a.x > a.z), s.world.xz, a.y > 0.8) / vec2f(1.2, 0.9);
  let pane = floor(uv);
  let f = fract(uv);
  let mullion = smoothstep(0.03, 0.07, min(min(f.x, 1.0 - f.x), min(f.y, 1.0 - f.y)));
  let paneHash = skyHash(pane.x * 17.0 + pane.y * 131.0 + bay);
  let grime = mix(0.35, 1.0, smoothstep(0.0, 0.9, f.y)) * mix(0.55, 1.0, fract(paneHash * 7.7));
  let dead = step(0.93, paneHash);
  o.emissive = s.emissive * 0.4 * tint * level * mullion * grime * (1.0 - dead) * mix(0.12, 1.0, smoothstep(6.0, 14.0, s.world.y));
  return o;
}

parameters.kernel:
// T1354b — furnace sparks (generated by src/projects/furnace/sparks-kernel.ts from the GLB markers).
struct Params {
  tapRate: f32, // @default 0.3  Share of this emitter's sparks alive (0..1).
  slagRate: f32, // @default 0.3  Share of this emitter's sparks alive (0..1).
  arcRate: f32, // @default 0.3  Share of this emitter's sparks alive (0..1).
  torchRate: f32, // @default 0.3  Share of this emitter's sparks alive (0..1).
  pourRate: f32, // @default 0.3  Share of this emitter's sparks alive (0..1).
  brightness: f32, // @default 6  HDR radiance of a fresh spark.
  streak: f32, // @default 0.035  Streak length in seconds of flight.
  gravity: f32, // @default 9.81  Metres per second squared.
};

const EMITTER_COUNT: u32 = 7u;
const EMITTER_ORIGIN = array<vec3f, 7>(vec3f(4.9500, 6.3000, 0.0000), vec3f(-3.8500, 9.3500, -0.3000), vec3f(-0.5889, 12.8000, 0.3400), vec3f(0.0000, 12.8000, -0.6800), vec3f(0.5889, 12.8000, 0.3400), vec3f(56.5000, 1.3750, 6.0000), vec3f(18.3300, 5.7000, 0.0000));
const EMITTER_DIRECTION = array<vec3f, 7>(vec3f(0.9439, 0.3304, 0.0000), vec3f(-0.9439, 0.3304, 0.0000), vec3f(0.0000, 1.0000, 0.0000), vec3f(0.0000, 1.0000, 0.0000), vec3f(0.0000, 1.0000, 0.0000), vec3f(0.0000, 0.1961, 0.9806), vec3f(0.9806, 0.1961, 0.0000));
// spread (radians), speed min, speed max, life min
const EMITTER_TUNING = array<vec4f, 7>(vec4f(0.550, 4.00, 9.00, 0.80), vec4f(0.600, 3.00, 9.00, 0.60), vec4f(0.700, 3.00, 9.00, 0.40), vec4f(0.700, 3.00, 9.00, 0.40), vec4f(0.700, 3.00, 9.00, 0.40), vec4f(0.350, 3.00, 7.00, 0.50), vec4f(0.600, 2.00, 6.00, 0.80));
const EMITTER_LIFE_MAX = array<f32, 7>(1.80, 1.50, 1.00, 1.00, 1.00, 1.20, 1.60);
const DRAG: f32 = 1.4;
const FLOOR: f32 = 0.03;

fn emitterRate(index: u32, ctx: PointCtx) -> f32 {
  switch index {
    case 0u: { return ctx.params.tapRate; }
    case 1u: { return ctx.params.slagRate; }
    case 2u: { return ctx.params.arcRate; }
    case 3u: { return ctx.params.arcRate; }
    case 4u: { return ctx.params.arcRate; }
    case 5u: { return ctx.params.torchRate; }
    case 6u: { return ctx.params.pourRate; }
    default: { return 0.0; }
  }
}

fn sparkHash(a: u32, b: u32) -> f32 {
  var h = a * 747796405u + b * 2891336453u + 12345u;
  h = ((h >> ((h >> 28u) + 4u)) ^ h) * 277803737u;
  h = (h >> 22u) ^ h;
  return f32(h) / 4294967295.0;
}

// Blackbody-ish ramp for a cooling spark: white-yellow fresh, deep orange, then red.
fn sparkHeat(heat: f32) -> vec3f {
  let h = clamp(heat, 0.0, 1.0);
  return mix(vec3f(1.0, 0.18, 0.02), mix(vec3f(1.0, 0.55, 0.12), vec3f(1.0, 0.92, 0.7), smoothstep(0.55, 1.0, h)), smoothstep(0.0, 0.55, h));
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let id = ctx.index;
  let emitter = id % EMITTER_COUNT;
  let tuning = EMITTER_TUNING[emitter];
  let life = mix(tuning.w, EMITTER_LIFE_MAX[emitter], sparkHash(id, 1u));
  let clock = ctx.absTime / life + sparkHash(id, 2u);
  let cycle = u32(floor(clock));
  let t = fract(clock) * life;
  let origin = EMITTER_ORIGIN[emitter];
  let alive = sparkHash(id, cycle * 7u + 3u) < clamp(emitterRate(emitter, ctx), 0.0, 1.0);
  if (!alive) {
    q.position = origin;
    q.endpoint = origin;
    q.tint = vec4f(0.0);
    return q;
  }
  // Launch: a cone around the emitter's direction, re-rolled every cycle.
  let axis = EMITTER_DIRECTION[emitter];
  let helper = select(vec3f(0.0, 1.0, 0.0), vec3f(1.0, 0.0, 0.0), abs(axis.y) > 0.9);
  let side = normalize(cross(axis, helper));
  let up = cross(side, axis);
  let angle = sparkHash(id, cycle * 7u + 4u) * 6.2831853;
  let tilt = sqrt(sparkHash(id, cycle * 7u + 5u)) * tuning.x;
  let direction = normalize(axis * cos(tilt) + (side * cos(angle) + up * sin(angle)) * sin(tilt));
  let speed = mix(tuning.y, tuning.z, sparkHash(id, cycle * 7u + 6u));
  let v0 = direction * speed;
  // Linear drag, closed form of dv/dt = g − k·v: v(t) = (v0 − g/k)e^{−kt} + g/k and
  // x(t) = x0 + (v0 − g/k)(1 − e^{−kt})/k + (g/k)·t. (The signs were once flipped, which
  // made gravity pull UP: sparks curling skyward.) At v0 = 0 and small t this is x0 + g·t²/2.
  let g = vec3f(0.0, -ctx.params.gravity, 0.0);
  let decay = exp(-DRAG * t);
  var position = origin + (v0 - g / DRAG) * (1.0 - decay) / DRAG + (g / DRAG) * t;
  var velocity = (v0 - g / DRAG) * decay + g / DRAG;
  // One bounce: fold below the floor, keep a third of the height and slow the skid.
  if (position.y < FLOOR) {
    position = vec3f(origin.x + (position.x - origin.x) * 0.85, FLOOR + (FLOOR - position.y) * 0.3, origin.z + (position.z - origin.z) * 0.85);
    velocity = vec3f(velocity.x * 0.5, -velocity.y * 0.3, velocity.z * 0.5);
  }
  let heat = 1.0 - t / life;
  q.position = position;
  q.endpoint = position - velocity * ctx.params.streak;
  // Cooling is fast: a spark is white-hot on the way up and nearly out by the time it falls.
  q.tint = vec4f(sparkHeat(heat) * ctx.params.brightness * heat * heat * heat, 1.0);
  return q;
}

parameters.source:
// @use surface-detail
struct Params {
  soot: f32, // @default 0.5  Soot darkening overall (0 clean .. 1 black).
  sootHeight: f32, // @default 18  Height in metres where soot is heaviest.
  furnaceSoot: f32, // @default 0.45  Extra soot near the furnace (within ~25 m).
  dust: f32, // @default 0.3  Pale dust on up-facing surfaces.
  streaks: f32, // @default 0.4  Rust-dark streaks down vertical faces.
  dents: f32, // @default 0.35  Strength of the dented, cast surface relief.
  wear: f32, // @default 0.7  Paint worn back to bare steel on edges.
  puddles: f32, // @default 0.8  Oily, glossy patches on the floor.
  floorGrime: f32, // @default 0.85  Scale, soot and slag ground into the floor.
  chalk: f32, // @default 0.45  How much chroma weathered paint has lost.
  paintPop: f32, // @default 0.35  Extra chroma on painted steel (fresh safety paint).
  fx: f32, // @default 0  Master level of the surface effects below (the director's intensity).
  kickSince: f32, // @default 100  Seconds since the kick: a shockwave runs out from the furnace along the panel seams.
  snareSince: f32, // @default 100  Seconds since the snare: a hot scanline sweeps up every wall.
  snareCount: f32, // @default 0  Running snare count: each snare's scanline gets its own width, shade and strength.
  beltTravel: f32, // @default 0  Conveyor belt travel, metres (drive with the rig's conveyor).
  lampHall: f32, // @default 1  The high-bay dimmer, as the lamp pass sees it.
  lampProps: f32, // @default 1  The low fixtures' dimmer.
  lampChase: f32, // @default 0  The chase running down the hall.
  lampFailing: f32, // @default 0.1  Share of failing ballasts.
  kickCount: f32, // @default 0  Running kick count: each kick re-picks WHICH parts of the plant the wave lights.
  flicker: f32, // @default 0  Hats: panels light up as corrupt blocks, hash-picked per 1.5 m panel.
  heatGlow: f32, // @default 14  (Legacy; the liquid and solid glows below replace it.)
  liquidGlow: f32, // @default 2  Radiance of liquid steel at its hottest.
  arcGlow: f32, // @default 6  Blue-white arc light leaking through the roof rings.
  arcFlash: f32, // @default 0  The arc's flash at the electrode ports (drive from the hats).
  fire: f32, // @default 18  Radiance of the flames inside the furnace (the audio's handle).
  liningGlow: f32, // @default 12  Radiance of hot SOLIDS — the strand, hot slag, graphite, linings.
  heatFlow: f32, // @default 0.3  How fast the molten surface flows, metres per second.
  heatPulse: f32, // @default 0  Extra heat on the whole melt (the audio's handle).
  crust: f32, // @default 0.8  How much slag floats on the molten surface.
};

// Temperature 0..1 to linear radiance colour: dull red, orange, yellow, near-white.
fn blackbody(t: f32) -> vec3f {
  let x = clamp(t, 0.0, 1.0);
  // Saturated through the orange: a camera sees molten steel as orange-yellow with a white
  // core only at the very top — and the grade's curve whitens whatever is left past it.
  let red = vec3f(0.6, 0.03, 0.0);
  let orange = vec3f(1.0, 0.22, 0.01);
  let yellow = vec3f(1.0, 0.5, 0.06);
  let white = vec3f(1.0, 0.82, 0.5);
  return mix(mix(red, orange, smoothstep(0.0, 0.35, x)), mix(yellow, white, smoothstep(0.9, 1.1, x)), smoothstep(0.35, 0.8, x));
}

// The audio's marks ON the steel — light running through the structure, not over the picture.
fn surfaceFx(s: SurfaceIn, p: Params) -> vec3f {
  if (p.fx <= 0.0) { return vec3f(0.0); }
  // Panel seams: distance to the nearest edge of the 1.5 m panel grid, on the face's plane.
  let cell = fract(s.world / 1.5);
  let edge = min(cell, vec3f(1.0) - cell);
  let across = abs(s.normal);
  let seamDistance = min(min(select(edge.x, 1.0, across.x > 0.7), select(edge.y, 1.0, across.y > 0.7)), select(edge.z, 1.0, across.z > 0.7));
  let seam = 1.0 - smoothstep(0.0, 0.04, seamDistance);
  // KICK: a ring leaving the furnace at 60 m/s, fading within a second; it lights the seams
  // hard and the panels faintly, so the structure itself carries the beat.
  let radius = p.kickSince * 60.0;
  let ring = exp(-pow((length(s.world.xz) - radius) / 0.8, 2.0)) * exp(-p.kickSince * 3.0);
  // The ring is hot at its leading edge and cools behind it — white, orange, deep red —
  // with a second, cold echo ring running a beat behind.
  let lead = exp(-pow((length(s.world.xz) - radius) / 0.5, 2.0));
  let wake = exp(-pow((length(s.world.xz) - radius + 3.0) / 2.5, 2.0));
  let echo = exp(-pow((length(s.world.xz) - radius * 0.6) / 0.6, 2.0)) * exp(-p.kickSince * 3.5);
  let fade = exp(-p.kickSince * 3.0);
  // SELECTIVE: each kick picks what answers, rotating through three ways of choosing —
  // scattered 6 m blocks, one horizontal band of the building, or only the machines — so the
  // whole plant never lights the same way twice in a row.
  let mode = u32(p.kickCount) % 3u;
  let block = floor(s.world / 6.0);
  let pickBlock = step(0.62, fract(sin(dot(block, vec3f(12.9898, 78.233, 37.719)) + p.kickCount * 3.17) * 43758.5453));
  let bandCentre = 2.0 + fract(p.kickCount * 0.618) * 24.0;
  let pickBand = 1.0 - smoothstep(1.5, 3.5, abs(s.world.y - bandCentre));
  let pickMachine = step(0.5, s.attr.w);
  let chosen = select(select(pickMachine, pickBand, mode == 1u), pickBlock, mode == 0u);
  var fx = ((vec3f(1.0, 0.9, 0.7) * lead * 6.0 + vec3f(1.0, 0.35, 0.05) * wake * 2.5) * fade * (seam * 1.5 + 0.08)
    + vec3f(0.2, 0.7, 1.0) * echo * seam * 2.5) * chosen;
  // SNARE: a thin scanline climbing the walls at 30 m/s, cold.
  // Each snare draws its own RED line: a hair or a band (0.06–0.5 m), blood red, crimson or
  // hot red-orange, faint to bright — so the climbing scanline never lands the same way twice.
  let h1 = fract(sin(p.snareCount * 12.9898) * 43758.5453);
  let h2 = fract(sin(p.snareCount * 78.233) * 43758.5453);
  let width = mix(0.04, 0.22, h1 * h1);
  let shade = select(select(vec3f(1.0, 0.25, 0.04), vec3f(0.9, 0.02, 0.08), h2 > 0.66), vec3f(1.0, 0.05, 0.02), h2 < 0.4);
  // Restrained: most lines a whisper, now and then one that burns.
  let strength = mix(0.2, 0.9, fract(h1 * 7.31 + h2)) + step(0.88, h2) * 0.8;
  let line = exp(-pow((s.world.y - p.snareSince * mix(18.0, 36.0, h2)) / width, 2.0)) * exp(-p.snareSince * 3.0) * (1.0 - across.y);
  fx = fx + shade * line * strength;
  // HATS: a few 3 m panels switching on as flat blocks, a new pick twelve times a second —
  // sparse, or it reads as confetti rather than a fault in the structure.
  let panel = floor(s.world / 3.0);
  let pick = fract(sin(dot(panel, vec3f(12.9898, 78.233, 37.719)) + floor(s.absTime * 12.0) * 7.13) * 43758.5453);
  fx = fx + vec3f(0.3, 0.75, 1.0) * step(1.0 - p.flicker * 0.012, pick) * 0.9;
  return fx * p.fx;
}

fn panelShade(world: vec3f) -> f32 {
  return detailNoise(floor(world / 1.5) + vec3f(0.5)).value;
}

fn materialClass(metal: f32, rough: f32, heat: f32) -> u32 {
  if (abs(metal - 0.0000) < 0.004 && abs(rough - 0.9000) < 0.004 && abs(heat - 0.0000) < 0.02) { return 6u; } // concrete
  if (abs(metal - 0.1000) < 0.004 && abs(rough - 0.9500) < 0.004 && abs(heat - 0.0000) < 0.02) { return 10u; } // slag_cold
  if (abs(metal - 0.3000) < 0.004 && abs(rough - 0.6200) < 0.004 && abs(heat - 0.0000) < 0.02) { return 1u; } // steel_painted_grey
  if (abs(metal - 0.8500) < 0.004 && abs(rough - 0.5200) < 0.004 && abs(heat - 0.0000) < 0.02) { return 2u; } // steel_dark
  if (abs(metal - 0.9500) < 0.004 && abs(rough - 0.3200) < 0.004 && abs(heat - 0.0000) < 0.02) { return 2u; } // steel_worn
  if (abs(metal - 0.8000) < 0.004 && abs(rough - 0.5800) < 0.004 && abs(heat - 0.0000) < 0.02) { return 4u; } // grating
  if (abs(metal - 0.1500) < 0.004 && abs(rough - 0.5500) < 0.004 && abs(heat - 0.0000) < 0.02) { return 1u; } // steel_painted_yellow
  if (abs(metal - 1.0000) < 0.004 && abs(rough - 0.3300) < 0.004 && abs(heat - 0.0000) < 0.02) { return 9u; } // copper_busbar
  if (abs(metal - 0.6500) < 0.004 && abs(rough - 0.5000) < 0.004 && abs(heat - 0.0000) < 0.02) { return 3u; } // roof_sheet
  if (abs(metal - 0.8500) < 0.004 && abs(rough - 0.4200) < 0.004 && abs(heat - 0.0000) < 0.02) { return 3u; } // steel_galvanized
  if (abs(metal - 0.0000) < 0.004 && abs(rough - 0.3000) < 0.004 && abs(heat - 0.0000) < 0.02) { return 12u; } // lamp
  if (abs(metal - 0.2000) < 0.004 && abs(rough - 0.4500) < 0.004 && abs(heat - 0.8500) < 0.02) { return 2u; } // graphite_hot
  if (abs(metal - 0.3000) < 0.004 && abs(rough - 0.4500) < 0.004 && abs(heat - 0.3500) < 0.02) { return 2u; } // graphite_warm
  if (abs(metal - 0.3500) < 0.004 && abs(rough - 0.4500) < 0.004 && abs(heat - 0.0000) < 0.02) { return 2u; } // graphite
  if (abs(metal - 0.0000) < 0.004 && abs(rough - 0.5500) < 0.004 && abs(heat - 0.0000) < 0.02) { return 8u; } // hose_red
  if (abs(metal - 0.1000) < 0.004 && abs(rough - 0.5000) < 0.004 && abs(heat - 0.0000) < 0.02) { return 1u; } // paint_black
  if (abs(metal - 0.6000) < 0.004 && abs(rough - 0.6200) < 0.004 && abs(heat - 0.0000) < 0.02) { return 2u; } // panel_cooled
  if (abs(metal - 0.0000) < 0.004 && abs(rough - 0.6200) < 0.004 && abs(heat - 0.0000) < 0.02) { return 8u; } // cable_rubber
  if (abs(metal - 0.2500) < 0.004 && abs(rough - 0.5500) < 0.004 && abs(heat - 0.0000) < 0.02) { return 1u; } // pipe_green
  if (abs(metal - 0.1500) < 0.004 && abs(rough - 0.6800) < 0.004 && abs(heat - 0.0000) < 0.02) { return 1u; } // steel_primer_red
  if (abs(metal - 0.0000) < 0.004 && abs(rough - 0.8800) < 0.004 && abs(heat - 0.0000) < 0.02) { return 7u; } // refractory
  if (abs(metal - 0.0000) < 0.004 && abs(rough - 0.8000) < 0.004 && abs(heat - 0.5500) < 0.02) { return 7u; } // refractory_hot
  if (abs(metal - 0.8000) < 0.004 && abs(rough - 0.4800) < 0.004 && abs(heat - 0.0000) < 0.02) { return 2u; } // steel_heat
  if (abs(metal - 0.8500) < 0.004 && abs(rough - 0.4600) < 0.004 && abs(heat - 0.0000) < 0.02) { return 4u; } // steel_chequer
  if (abs(metal - 0.0000) < 0.004 && abs(rough - 0.8000) < 0.004 && abs(heat - 0.0000) < 0.02) { return 11u; } // rubber_belt
  if (abs(metal - 0.2500) < 0.004 && abs(rough - 0.5500) < 0.004 && abs(heat - 0.0000) < 0.02) { return 1u; } // steel_painted_blue
  if (abs(metal - 0.6000) < 0.004 && abs(rough - 0.7800) < 0.004 && abs(heat - 0.0000) < 0.02) { return 5u; } // scrap_mix
  if (abs(metal - 0.3500) < 0.004 && abs(rough - 0.8500) < 0.004 && abs(heat - 0.0000) < 0.02) { return 5u; } // rust
  return 0u;
}
const ELECTRODE_PORT = array<vec2f, 3>(vec2f(-0.5889, 0.3400), vec2f(0.0000, -0.6800), vec2f(0.5889, 0.3400));

struct Skin {
  albedo: vec3f,
  roughness: f32,
  metallic: f32,
  normal: vec3f,
  // 1 where paint has flaked to the metal beneath (the generic wear then leaves it alone).
  exposed: f32,
};

// Two coordinates ON the face: the world projected along the face's dominant axis.
fn faceUv(world: vec3f, normal: vec3f) -> vec2f {
  let a = abs(normal);
  if (a.x > a.y && a.x > a.z) { return world.zy; }
  if (a.z > a.y) { return world.xy; }
  return world.xz;
}

fn cellHash(c: vec2f) -> f32 {
  return fract(sin(dot(c, vec2f(127.1, 311.7))) * 43758.5453);
}

// Rust, in three layers: dark iron oxide, orange bloom, ochre dust.
fn rustColour(n: f32) -> vec3f {
  return mix(mix(vec3f(0.09, 0.035, 0.015), vec3f(0.34, 0.11, 0.03), smoothstep(0.3, 0.6, n)), vec3f(0.42, 0.24, 0.08), smoothstep(0.7, 0.9, n));
}

fn classSkin(kind: u32, s: SurfaceIn, base: vec3f, normal: vec3f, p: Params) -> Skin {
  var k: Skin;
  k.albedo = base;
  k.roughness = s.roughness;
  k.metallic = s.metallic;
  k.normal = normal;
  k.exposed = 0.0;
  let w = s.world;
  let fp = s.footprint;
  switch kind {
    case 1u: {
      // PAINT: chips flake down to RUST (not bright metal), rust bleeds in streaks below them,
      // and runs of thicker paint catch the light.
      let chip = detailFbm(w * 2.6, 4, fp).value;
      let edge = detailEdgeWear(s.curvature, 5.0, chip);
      let flake = clamp(max(edge, smoothstep(0.66, 0.74, chip)) * p.wear, 0.0, 1.0);
      let bleed = smoothstep(0.62, 0.8, detailFbm(vec3f(w.x * 5.0, w.y * 0.35, w.z * 5.0), 3, fp).value) * (1.0 - abs(normal.y));
      let rust = rustColour(detailFbm(w * 7.0, 3, fp).value);
      k.albedo = mix(mix(base, base * vec3f(0.62, 0.42, 0.3), bleed * 0.7), rust, flake);
      k.roughness = mix(0.42 + 0.2 * chip, 0.85, flake);
      k.metallic = mix(0.05, 0.3, flake);
      k.normal = detailBump(normal, detailFbm(w * 2.6, 3, fp).gradient, 0.05 + flake * 0.12);
      k.exposed = flake;
    }
    case 2u: {
      // BARE STEEL: brushed along the part, blue-black mill scale in islands, and TEMPER
      // colours near the furnace — straw, bronze, purple, blue with rising heat.
      let brush = detailFbm(vec3f(w.x * 40.0, w.y * 1.5, w.z * 40.0), 2, fp).value;
      let scale = smoothstep(0.45, 0.62, detailFbm(w * 1.1, 4, fp).value);
      let near = 1.0 - smoothstep(4.0, 16.0, length(w.xz));
      let temper = clamp(near * (0.55 + 0.6 * detailFbm(w * 0.6, 3, fp).value) + p.heatPulse * near * 0.3, 0.0, 1.0);
      let tint = mix(mix(vec3f(0.62, 0.5, 0.26), vec3f(0.5, 0.26, 0.12), smoothstep(0.2, 0.45, temper)), mix(vec3f(0.3, 0.12, 0.32), vec3f(0.12, 0.2, 0.42), smoothstep(0.7, 0.9, temper)), smoothstep(0.45, 0.7, temper));
      var steel = base * (0.75 + 0.5 * brush);
      steel = mix(steel, vec3f(0.035, 0.04, 0.05), scale * 0.8);
      k.albedo = mix(steel, tint * (0.6 + 0.4 * brush), smoothstep(0.12, 0.3, temper) * 0.85);
      k.roughness = clamp(mix(0.28 + 0.25 * brush, 0.7, scale), 0.08, 1.0);
      k.metallic = mix(0.95, 0.55, scale);
      k.normal = detailBump(normal, detailFbm(w * 3.0, 3, fp).gradient, 0.04);
    }
    case 3u: {
      // GALVANIZED: spangle — crystal cells of slightly different sheen — and white rust.
      let uv = faceUv(w, normal) * 9.0;
      let spangle = cellHash(floor(uv + detailNoise(vec3f(uv, 0.0) * 0.5).value));
      let whiteRust = smoothstep(0.6, 0.78, detailFbm(w * 1.4, 4, fp).value);
      k.albedo = mix(base * (0.8 + 0.45 * spangle), vec3f(0.55, 0.56, 0.55), whiteRust * 0.7);
      k.roughness = mix(0.22 + 0.3 * spangle, 0.9, whiteRust);
      k.metallic = mix(0.9, 0.2, whiteRust);
    }
    case 4u: {
      // CHEQUER PLATE: raised lozenges in alternating directions, polished bright by boots on
      // top, grime packed between them.
      let uv = faceUv(w, normal) * 3.2;
      let cell = floor(uv);
      let f = fract(uv) - 0.5;
      let turn = select(vec2f(f.x + f.y, f.x - f.y), vec2f(f.x - f.y, f.x + f.y), (i32(cell.x + cell.y) & 1) == 1) * 0.7071;
      let lozenge = 1.0 - smoothstep(0.06, 0.1, length(vec2f(turn.x * 0.28, turn.y)));
      let grad = vec3f(-turn.x, 0.0, -turn.y) * lozenge * 3.0;
      let worn = lozenge * abs(normal.y);
      k.albedo = mix(base * 0.7, vec3f(0.5, 0.5, 0.5), worn * 0.8);
      k.roughness = mix(0.62, 0.22, worn);
      k.metallic = 0.9;
      k.normal = detailBump(normal, grad, 0.18);
    }
    case 5u: {
      // RUST: flaky, layered, pitted.
      let n = detailFbm(w * 4.0, 4, fp);
      k.albedo = rustColour(n.value) * (0.7 + 0.6 * detailFbm(w * 0.8, 2, fp).value);
      k.roughness = 0.9;
      k.metallic = 0.15;
      k.normal = detailBump(normal, n.gradient, 0.3);
    }
    case 6u: {
      // CONCRETE: aggregate, cracks, oil stains, and painted walkway lines on the floor.
      let aggregate = detailFbm(w * 14.0, 2, fp).value;
      let crackField = detailFbm(vec3f(w.x, 0.0, w.z) * 0.35, 4, fp).value;
      let crack = 1.0 - smoothstep(0.004, 0.018, abs(crackField - 0.5));
      let oil = smoothstep(0.55, 0.7, detailFbm(w * 0.25 + vec3f(7.0), 4, fp).value);
      let floorFace = smoothstep(0.9, 0.97, normal.y);
      let lane = floorFace * (1.0 - smoothstep(0.07, 0.1, abs(fract(w.z / 9.0 + 0.5) - 0.5) * 9.0 - 3.6)) * step(0.25, fract(w.x / 3.0));
      var c = base * (0.8 + 0.4 * aggregate);
      c = mix(c, vec3f(0.02, 0.018, 0.016), crack * 0.85);
      c = mix(c, c * 0.3, oil * floorFace);
      // Walkway lines: worn, dirty — a trace of paint, not a fresh yellow stripe.
      c = mix(c, vec3f(0.42, 0.3, 0.06) * (0.5 + 0.5 * aggregate), lane * 0.45 * smoothstep(0.35, 0.6, aggregate));
      k.albedo = c;
      k.roughness = mix(mix(0.9, 0.12, oil * floorFace), 0.5, lane);
      k.metallic = 0.0;
      k.normal = detailBump(normal, detailFbm(w * 6.0, 3, fp).gradient, 0.08);
    }
    case 7u: {
      // REFRACTORY: brick courses in running bond, each brick its own shade, dark mortar.
      let uv = faceUv(w, normal) / vec2f(0.46, 0.14);
      let row = floor(uv.y);
      let brickUv = vec2f(uv.x + 0.5 * (row % 2.0), uv.y);
      let brick = floor(brickUv);
      let f = fract(brickUv);
      let mortar = 1.0 - smoothstep(0.03, 0.07, min(min(f.x, 1.0 - f.x) * 0.46 / 0.14, min(f.y, 1.0 - f.y)));
      let shade = cellHash(brick);
      k.albedo = mix(base * (0.65 + 0.6 * shade) * vec3f(1.0, 0.92, 0.85), vec3f(0.05, 0.045, 0.04), mortar);
      k.roughness = 0.92;
      k.metallic = 0.0;
      k.normal = detailBump(normal, vec3f(f.x - 0.5, f.y - 0.5, 0.0) * mortar * 2.0, 0.2);
    }
    case 8u: {
      // RUBBER: dark satin, dust in the grain.
      let grainy = detailFbm(w * 20.0, 2, fp).value;
      k.albedo = base * (0.8 + 0.4 * grainy);
      k.roughness = 0.55 + 0.2 * grainy;
      k.metallic = 0.0;
    }
    case 9u: {
      // COPPER: bright on the edges, verdigris and dark tarnish in the flats.
      let tarnish = detailFbm(w * 2.0, 3, fp).value;
      let edge = detailEdgeWear(s.curvature, 4.0, tarnish);
      let verdigris = smoothstep(0.62, 0.75, tarnish) * (1.0 - edge);
      k.albedo = mix(mix(base * 0.45, base * 1.25, edge), vec3f(0.12, 0.3, 0.24), verdigris);
      k.roughness = mix(mix(0.45, 0.2, edge), 0.8, verdigris);
      k.metallic = mix(1.0, 0.1, verdigris);
    }
    case 10u: {
      // COLD SLAG: glassy black, bubbled, an oil-slick sheen where it is smooth.
      let bubbles = detailFbm(w * 9.0, 3, fp);
      let sheen = 0.5 + 0.5 * sin(bubbles.value * 18.0 + vec3f(0.0, 2.1, 4.2));
      k.albedo = mix(vec3f(0.02), sheen * 0.08, smoothstep(0.5, 0.7, bubbles.value));
      k.roughness = mix(0.25, 0.9, bubbles.value);
      k.metallic = 0.3;
      k.normal = detailBump(normal, bubbles.gradient, 0.35);
    }
    case 11u: {
      // CONVEYOR BELT: its u runs along travel in metres, and the belt's travel is added HERE —
      // the mesh draw reads the file's UVs, not the rig's, so a rig scroll never reached it.
      // Everything drawn in u rides the belt: cleats every 0.6 m and a load of scrap chunks.
      let u = s.uv.x - p.beltTravel;
      let across = s.uv.y;
      let cleat = 1.0 - smoothstep(0.02, 0.05, abs(fract(u / 0.6) - 0.5) * 0.6);
      let chunkCell = vec2f(floor(u * 2.5), floor(across * 6.0));
      let chunkHash = cellHash(chunkCell);
      let local = vec2f(fract(u * 2.5), fract(across * 6.0)) - 0.5;
      let chunk = step(0.35, chunkHash) * (1.0 - smoothstep(0.2, 0.42, length(local * vec2f(1.0, 1.4))));
      let bump = vec3f(local.x, 0.0, local.y) * chunk * 3.0;
      k.albedo = mix(mix(base, base * 2.5, cleat), vec3f(0.12, 0.09, 0.07) * (0.6 + 0.8 * chunkHash), chunk);
      k.roughness = mix(0.8, 0.7, chunk);
      k.metallic = chunk * 0.6;
      k.normal = detailBump(normal, bump, 0.35);
      k.exposed = 0.0;
    }
    default: {}
  }
  return k;
}

// Inside the furnace shell (radius ~4.2 m about the vertical axis, between the hearth and the
// roof): flames licking up the walls and a foaming, boiling slag line — what the slag door
// and the roof gaps show. Advected upward, broken by noise, flickering with the music.
fn furnaceInterior(s: SurfaceIn, p: Params) -> vec3f {
  let r = length(s.world.xz);
  // Only the LINING: a surface inside the radius whose normal faces the axis (the shell's
  // outer skin faces away, and must stay steel).
  let inward = smoothstep(0.2, 0.6, dot(s.normal.xz, -s.world.xz / max(r, 1e-3)));
  // (No up-facing term: the bath is the liquid material's own; an up-facing test lit the
  // working platform's tops white under the shell.)
  // Above the bath only (8.8 m): below it the inward faces are the platform's beams under the shell.
  let inside = (1.0 - smoothstep(3.6, 4.2, r)) * inward * smoothstep(8.8, 9.2, s.world.y) * (1.0 - smoothstep(12.0, 13.0, s.world.y));
  if (inside <= 0.0 || p.fire <= 0.0) { return vec3f(0.0); }
  let t = s.absTime;
  let rise = vec3f(s.world.x * 1.3, s.world.y * 0.9 - t * 2.6, s.world.z * 1.3);
  let tongues = detailFbm(rise, 4, s.footprint).value;
  let flicker = detailFbm(vec3f(s.world.xz * 0.7, t * 3.0), 2, s.footprint).value;
  let height = 1.0 - smoothstep(8.0, 12.5, s.world.y);
  let flame = smoothstep(0.42, 0.75, tongues * (0.6 + 0.6 * flicker) + height * 0.3);
  // The slag line: a boiling band around the bath level.
  let foam = smoothstep(0.45, 0.7, detailFbm(vec3f(s.world.xz * 2.2, t * 1.8), 3, s.footprint).value) * (1.0 - smoothstep(0.0, 0.9, abs(s.world.y - 8.9)));
  let temperature = clamp(0.55 + 0.45 * flame + 0.3 * foam, 0.0, 1.0);
  return blackbody(temperature) * p.fire * inside * (flame * flame + foam * 0.8);
}

// The slag door's back plate is a PORTAL (interior mapping): the view ray continues through
// it into a virtual furnace, and what it meets there is shaded — the churning bath at the
// slag line, flames boiling up off it, the far wall glowing. A flat hot plate in the model
// becomes a hole into a furnace.
fn doorPortal(s: SurfaceIn, p: Params) -> vec4f {
  let w = s.world;
  let onPlate = step(-3.62, w.x) * step(w.x, -3.2) * step(abs(w.z), 0.78) * step(8.8, w.y) * step(w.y, 10.55) * step(0.6, -s.normal.x);
  if (onPlate <= 0.0) { return vec4f(0.0); }
  let ray = normalize(w - s.eye);
  // The bath, 0.25 m below the sill, reaching deep into the shell.
  let bathY = 8.6;
  var colour = vec3f(0.0);
  if (ray.y < -0.02) {
    let t = (bathY - w.y) / ray.y;
    let hit = w + ray * t;
    let flow = vec3f(s.absTime * 0.35, 0.0, s.absTime * 0.2);
    let cells = detailFbm(hit * 1.1 - flow, 3, s.footprint).value;
    let churn = detailFbm(hit * 3.5 - flow * 1.8, 3, s.footprint).value;
    let temperature = clamp(0.45 + 0.4 * cells + 0.25 * churn, 0.0, 1.1);
    colour = blackbody(temperature) * p.liquidGlow * 6.0 * temperature * temperature * exp(-t * 0.08);
  }
  // Flames: a slab of turbulent fire filling the space, sampled along the ray.
  var flames = 0.0;
  for (var k = 1; k <= 6; k = k + 1) {
    let x = w + ray * f32(k) * 0.55;
    let rise = vec3f(x.x * 1.4, x.y * 1.1 - s.absTime * 3.2, x.z * 1.4);
    let tongue = smoothstep(0.5, 0.8, detailFbm(rise, 3, s.footprint).value) * (1.0 - smoothstep(9.0, 11.5, x.y));
    flames = flames + tongue * 0.3;
  }
  colour = colour + blackbody(0.8) * p.fire * 0.35 * flames;
  return vec4f(colour, 1.0);
}

// Burning gas at the electrode PORTS (where each electrode passes the roof): a ring of
// flickering flame hugging the electrode, flaring white-blue with the arc.
fn electrodePorts(s: SurfaceIn, p: Params) -> vec3f {
  if (s.world.y < 12.0 || s.world.y > 14.2) { return vec3f(0.0); }
  var glow = vec3f(0.0);
  for (var k = 0u; k < 3u; k = k + 1u) {
    let d = length(s.world.xz - ELECTRODE_PORT[k]);
    let ring = 1.0 - smoothstep(0.35, 1.0, d);
    if (ring <= 0.0) { continue; }
    let lick = detailFbm(vec3f(s.world.xz * 3.0, s.world.y * 2.0 - s.absTime * 4.0 + f32(k) * 7.0), 3, s.footprint).value;
    let low = 1.0 - smoothstep(12.6, 14.0, s.world.y);
    let flame = smoothstep(0.35, 0.75, lick) * ring * low;
    glow = glow + blackbody(0.7 + 0.3 * lick) * flame * p.fire * 0.45 + vec3f(0.6, 0.75, 1.0) * ring * low * p.arcFlash;
  }
  return glow;
}

// A lamp HEAD glows as its light does: the hall dimmer (with its kick flashes, strobes and
// blackouts), the chase down the hall, and the failing ballasts — the file's fixed emission
// never followed the programme, so the light changed while the lamp did not.
fn lampHeadLevel(s: SurfaceIn, p: Params) -> f32 {
  let cell = floor(s.world / 2.0);
  let hash = fract(sin(dot(cell, vec3f(12.9898, 78.233, 37.719))) * 43758.5453);
  let failing = step(1.0 - p.lampFailing, hash) * step(0.55, fract(sin(floor(s.absTime * 13.0 + hash * 50.0) * 12.9898) * 43758.5453));
  let wave = 0.5 + 0.5 * sin(s.world.x * 0.22 - s.absTime * 6.0);
  let chase = mix(1.0, wave * wave * 1.8, p.lampChase);
  let dimmer = select(p.lampProps, p.lampHall, s.world.y > 22.0);
  return dimmer * chase * (1.0 - failing) * 2.0;
}

// The ARC seen through the roof: blue-white light leaking between the water-cooled coil
// rings of the roof, flickering like an arc hunts and flaring on the hats — the cold light
// of the process against the orange of the melt. Bright enough to bloom.
fn roofArcGlow(s: SurfaceIn, p: Params) -> vec3f {
  let r = length(s.world.xz);
  if (s.world.y < 12.0 || s.world.y > 14.8 || r > 4.3 || s.normal.y < 0.2) { return vec3f(0.0); }
  let gap = smoothstep(0.82, 0.96, abs(fract(r * 5.0) - 0.5) * 2.0);
  let hunt = detailFbm(vec3f(s.world.xz * 1.5, s.absTime * 6.0), 2, s.footprint).value;
  let edge = 1.0 - smoothstep(3.6, 4.3, r);
  return vec3f(0.42, 0.62, 1.0) * gap * edge * p.arcGlow * (0.45 + 0.9 * hunt) * (1.0 + p.arcFlash * 0.5);
}

fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
  var o = surfaceBody(s, p);
  o.emissive = o.emissive + roofArcGlow(s, p);
  if (materialClass(s.metallic, s.roughness, s.attr.z) == 12u) {
    // The file's lamp emission (40) is a Blender-Cycles figure; here a head at full dimmer reads as a bright lens, not a white slab.
    o.emissive = s.emissive * lampHeadLevel(s, p) * 0.12;
    return o;
  }
  o.emissive = o.emissive + electrodePorts(s, p);
  let portal = doorPortal(s, p);
  if (portal.w > 0.0) {
    o.albedo = vec4f(vec3f(0.0), s.albedo.a);
    o.emissive = portal.rgb;
    o.roughness = 1.0;
    o.metallic = 0.0;
    return o;
  }
  o.emissive = o.emissive + furnaceInterior(s, p);
  return o;
}

fn surfaceBody(s: SurfaceIn, p: Params) -> SurfaceOut {
  var o = surfaceDefaults(s);
  let heat = s.attr.z;

  if (heat >= 0.9) {
    // LIQUID STEEL, read at a camera's distance: a surface of CELLS — bright upwellings
    // bounded by darker, cooling seams (Voronoi-like, from the distance to the nearest of a
    // jittered grid), crossed by black slag rafts that drift and tear, fume lifting off.
    let flow = vec3f(s.absTime * p.heatFlow, 0.0, s.absTime * p.heatFlow * 0.6);
    let q = s.world.xz * 1.3 + vec2f(detailNoise(vec3f(s.world.xz * 0.8, s.absTime * 0.3)).value) * 0.9;
    let cell = floor(q);
    var nearest = 9.0;
    var second = 9.0;
    for (var j = -1; j <= 1; j = j + 1) {
      for (var i = -1; i <= 1; i = i + 1) {
        let c = cell + vec2f(f32(i), f32(j));
        let h = fract(sin(vec2f(dot(c, vec2f(127.1, 311.7)), dot(c, vec2f(269.5, 183.3)))) * 43758.5453);
        let site = c + 0.5 + 0.4 * sin(h * 6.2831 + s.absTime * (0.6 + h));
        let d = length(q - site);
        if (d < nearest) { second = nearest; nearest = d; } else if (d < second) { second = d; }
      }
    }
    let seam = 1.0 - smoothstep(0.02, 0.22, second - nearest);
    let churn = detailFbm(s.world * 3.2 - flow * 1.7 + vec3f(0.0, s.absTime * 0.4, 0.0), 3, s.footprint);
    let rafts = smoothstep(0.5, 0.6, detailFbm(s.world * 0.7 - flow * 0.4, 3, s.footprint).value);
    let skin = clamp(rafts * p.crust * (1.0 - p.heatPulse * 0.6), 0.0, 1.0);
    let raftCracks = (1.0 - smoothstep(0.02, 0.06, abs(churn.value - 0.5))) * skin;
    let core = 1.0 - smoothstep(0.0, 0.55, nearest);
    let temperature = clamp(heat * (0.45 + 0.35 * core + 0.3 * churn.value - 0.18 * seam) + p.heatPulse * 0.25, 0.0, 1.1);
    let glow = blackbody(temperature) * p.liquidGlow * temperature * temperature * (1.0 - 0.3 * seam);
    o.emissive = glow * (1.0 - skin * 0.985) + blackbody(0.6) * p.liquidGlow * 0.6 * raftCracks;
    o.albedo = vec4f(vec3f(0.03, 0.026, 0.024) * (0.5 + skin), s.albedo.a);
    o.roughness = mix(0.1, 0.85, skin);
    o.metallic = 0.0;
    o.normal = detailBump(s.normal, churn.gradient * (1.0 - skin) * 0.5 + vec3f(q.x - cell.x - 0.5, 0.0, q.y - cell.y - 0.5) * seam, 0.15 + skin * 0.2);
    return o;
  }

  if (heat > 0.01) {
    // HOT SOLIDS (the strand, hot slag, graphite, refractory): BLAZING — a solid at 1200 °C is
    // a light source. Orange-yellow body, brighter cracks, a darker oxide scale that breaks.
    // Hot SLAG creeps DOWNHILL: its pattern advects along the surface's own fall line (gravity
    // projected into the tangent plane), so a spill over the apron runs, a flat pool barely moves.
    let fall = vec3f(0.0, -1.0, 0.0) - s.normal * dot(vec3f(0.0, -1.0, 0.0), s.normal);
    let isSlag = step(s.metallic, 0.05) * step(0.65, s.roughness);
    let slagFlow = select(vec3f(0.0), fall * s.absTime * 0.8, isSlag > 0.5);
    // Each kick sends a SURGE of fresh slag down the fall line: a bright band leaving the sill
    // (y ≈ 8.9 m) and running down the apron at 3 m/s, cooling as it goes.
    let drop = 8.9 - s.world.y;
    let surge = isSlag * exp(-pow((drop - p.kickSince * 3.0) / 0.35, 2.0)) * exp(-p.kickSince * 1.2) * step(-0.2, drop);
    if (isSlag > 0.5 && length(fall) > 0.2) {
      // A RUNNING slag stream: the pattern stretched along the fall line and advected down it —
      // hot orange ropes between dark, cooling crust, never a flat lit sheet.
      let down = normalize(fall);
      let across = normalize(cross(s.normal, down));
      let q = vec3f(dot(s.world, across) * 5.0, dot(s.world, down) * 1.1 - s.absTime * 2.2, dot(s.world, s.normal));
      let ropes = detailFbm(q, 4, s.footprint);
      let hot = smoothstep(0.4, 0.78, ropes.value) + surge;
      let temperature = clamp(0.3 + 0.4 * ropes.value + surge * 0.3, 0.0, 1.0);
      o.emissive = blackbody(temperature) * p.liningGlow * 0.3 * hot * hot;
      o.albedo = vec4f(vec3f(0.03, 0.025, 0.022), s.albedo.a);
      o.roughness = mix(0.9, 0.3, hot);
      o.metallic = 0.0;
      o.normal = detailBump(s.normal, ropes.gradient, 0.3);
      return o;
    }
    let grain = detailFbm((s.world - slagFlow) * 2.4, 4, s.footprint);
    let crackField = detailFbm((s.world - slagFlow) * 0.9, 3, s.footprint).value;
    let cracks = 1.0 - smoothstep(0.012, 0.05, abs(crackField - 0.5));
    // Hot SLAG (dielectric, rough) is a black crust that glows only in its fissures; hot steel
    // (the strand, graphite) glows through a thin, breaking oxide.
    let slag = step(s.metallic, 0.05) * step(0.65, s.roughness) * step(heat, 0.8);
    let oxide = mix(smoothstep(0.55, 0.75, detailFbm(s.world * 1.6, 3, s.footprint).value) * (1.0 - heat * 0.6), 1.0 - cracks, slag);
    let temperature = clamp(heat * (0.75 + 0.35 * grain.value) + cracks * 0.3 * heat + p.heatPulse * 0.25, 0.0, 1.0);
    // Slag glows in its fissures and its surges, dim elsewhere; a hot SOLID blazes.
    let body = mix(1.0, 0.25, isSlag);
    o.emissive = blackbody(temperature) * p.liningGlow * body * temperature * temperature * (1.0 - oxide * 0.8) + blackbody(0.85) * p.liningGlow * surge * 1.2;
    o.albedo = vec4f(s.albedo.rgb * 0.4, s.albedo.a);
    o.roughness = mix(0.6, 0.95, oxide);
    o.metallic = 0.0;
    o.normal = detailBump(s.normal, grain.gradient, 0.25);
    return o;
  }

  // ── COLD SURFACES ──
  let base = s.albedo.rgb;
  let brightest = max(base.r, max(base.g, base.b));
  let saturation = (brightest - min(base.r, min(base.g, base.b))) / max(brightest, 1e-3);
  let painted = smoothstep(0.25, 0.45, saturation);
  let concrete = (1.0 - smoothstep(0.02, 0.1, s.metallic)) * smoothstep(0.7, 0.85, s.roughness) * (1.0 - painted);
  let up = clamp(s.normal.y, -1.0, 1.0);
  let vertical = 1.0 - abs(up);
  let isFloor = smoothstep(0.9, 0.97, up) * (1.0 - smoothstep(0.25, 0.6, s.world.y));

  // Relief: broad dents plus fine cast grain; concrete gets pitting instead of dents.
  let dents = detailFbm(s.world * 0.7, 3, s.footprint);
  let grain = detailFbm(s.world * 9.0, 3, s.footprint);
  let reliefGradient = dents.gradient * mix(0.5, 0.15, concrete) + grain.gradient * mix(0.04, 0.09, concrete);
  var normal = detailBump(s.normal, reliefGradient, p.dents * 0.12);

  // Macro variation per panel, and a slow blotch for grime to key off.
  let panel = panelShade(s.world);
  let blotch = detailFbm(s.world * 0.3, 3, s.footprint).value;
  var albedo = base * (0.82 + 0.36 * panel);
  // Paint in a melt shop is chalked and filmed with dust: it keeps its hue but loses its
  // chroma, which is also what stops blue paint under orange light going violet.
  albedo = mix(vec3f(dot(albedo, vec3f(0.2126, 0.7152, 0.0722))), albedo, 1.0 - painted * p.chalk);
  // …and where it is fresh it is the loudest colour in the shop: safety yellow, primer red.
  albedo = mix(albedo, albedo * albedo / max(dot(albedo, vec3f(0.2126, 0.7152, 0.0722)), 1e-3) * 0.9, painted * p.paintPop);

  // The surface CLASS (from the file's own material table) draws its own texture.
  let kind = materialClass(s.metallic, s.roughness, s.attr.z);
  var metallic = s.metallic;
  var roughness = s.roughness;
  var wear = 0.0;
  if (kind != 0u) {
    let skin = classSkin(kind, s, albedo, normal, p);
    albedo = skin.albedo;
    roughness = skin.roughness;
    metallic = skin.metallic;
    normal = skin.normal;
    wear = skin.exposed;
  } else {
    // Unclassified: paint worn back to bare steel on edges, and a little where it is knocked.
    let chips = detailFbm(s.world * 3.2, 3, s.footprint).value;
    wear = painted * p.wear * max(detailEdgeWear(s.curvature, 6.0, chips), smoothstep(0.72, 0.85, chips) * 0.5);
    albedo = mix(albedo, vec3f(0.42, 0.41, 0.4), wear);
    metallic = mix(s.metallic, 0.95, wear);
    roughness = mix(s.roughness, 0.32, wear);
  }

  // Soot by height and by the furnace; dust on top faces; streaks down walls.
  let heightSoot = smoothstep(2.0, p.sootHeight, s.world.y);
  let nearFurnace = 1.0 - smoothstep(6.0, 26.0, length(s.world.xz));
  let sootAmount = clamp(p.soot * (0.3 + 0.7 * heightSoot) * (0.55 + 0.9 * blotch) + p.furnaceSoot * nearFurnace * blotch, 0.0, 0.92);
  let streak = smoothstep(0.58, 0.8, detailFbm(vec3f(s.world.x * 3.1, s.world.y * 0.16, s.world.z * 3.1), 3, s.footprint).value) * vertical * p.streaks;
  let dustAmount = smoothstep(0.6, 0.95, up) * p.dust * (0.4 + blotch) * (1.0 - isFloor * 0.6);
  albedo = mix(albedo, albedo * vec3f(0.5, 0.36, 0.26), streak);
  albedo = mix(albedo, vec3f(0.016, 0.014, 0.013), sootAmount * (1.0 - wear * 0.5));
  albedo = mix(albedo, vec3f(0.3, 0.28, 0.25), dustAmount);
  albedo = mix(albedo, albedo * vec3f(0.78, 0.74, 0.7), concrete * smoothstep(0.45, 0.75, blotch));
  // A melt-shop floor is never clean concrete: ground-in scale and soot take it dark, with
  // paler tracks where the traffic scuffs it and black slag spatter near the furnace.
  let tracks = smoothstep(0.55, 0.75, detailFbm(vec3f(s.world.x * 0.12, 0.0, s.world.z * 0.9), 3, s.footprint).value);
  let spatter = smoothstep(0.7, 0.78, detailFbm(s.world * 1.7, 3, s.footprint).value) * (1.0 - smoothstep(8.0, 22.0, length(s.world.xz)));
  let grime = isFloor * p.floorGrime;
  albedo = mix(albedo, albedo * vec3f(0.34, 0.32, 0.3) * (0.7 + 0.8 * tracks), grime);
  albedo = mix(albedo, vec3f(0.02, 0.018, 0.017), spatter * grime);

  // Roughness breakup: nothing in a steel shop is evenly glossy.
  roughness = clamp(roughness * (0.72 + 0.56 * grain.value) + sootAmount * 0.25 + dustAmount * 0.35 - streak * 0.08, 0.06, 1.0);
  metallic = metallic * (1.0 - dustAmount) * (1.0 - sootAmount * 0.6);

  // The floor: oily, damp patches go dark and glossy and flatten the relief.
  let wet = isFloor * p.puddles * smoothstep(0.52, 0.64, detailFbm(s.world * 0.22 + vec3f(3.1), 4, s.footprint).value);
  albedo = mix(albedo, albedo * 0.35, wet);
  roughness = mix(roughness, 0.05, wet);
  normal = normalize(mix(normal, s.normal, wet));

  o.albedo = vec4f(albedo, s.albedo.a);
  o.roughness = roughness;
  o.metallic = metallic;
  o.normal = normal;
  o.emissive = o.emissive + surfaceFx(s, p);
  return o;
}

struct Params {
  eye: vec3f, // @default 0  Camera position (drive from the camera).
  aim: vec3f, // @default 0  Camera look-at (drive from the camera).
  fov: f32, // @default 50  Camera vertical field of view, degrees.
  far: f32, // @default 400  Camera far plane (depth arrives as distance ÷ far).
  roll: f32, // @default 0  Camera roll, degrees (drive from the camera).
  prevEye: vec3f, // @default 0  The camera's position one frame ago.
  prevAim: vec3f, // @default 0  The camera's look-at one frame ago.
  prevFov: f32, // @default 50  The camera's fov one frame ago.
  prevRoll: f32, // @default 0  The camera's roll one frame ago, degrees.
  blend: f32, // @default 0.12  Share of the new frame each frame.
  reset: f32, // @default 0  Above 0.5 the history is dropped (a cut).
};
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;
@group(0) @binding(5) var inputTexture2: texture_2d<f32>;

// T1383b: the camera's right vector with its ROLL — world up turned about the view axis by
// roll degrees (Rodrigues), exactly as camera.ts guardedRolledUp builds the render's view.
fn rolledRight(forward: vec3f, rollDeg: f32) -> vec3f {
  var up = select(vec3f(0.0, 1.0, 0.0), vec3f(0.0, 0.0, 1.0), abs(forward.y) > 0.999);
  let t = radians(rollDeg);
  up = up * cos(t) + cross(forward, up) * sin(t) + forward * dot(forward, up) * (1.0 - cos(t));
  return normalize(cross(forward, up));
}

struct View {
  forward: vec3f,
  right: vec3f,
  up: vec3f,
  tanHalf: f32,
  aspect: f32,
};

fn makeView() -> View {
  var v: View;
  v.forward = normalize(params.aim - params.eye);
  v.right = rolledRight(v.forward, params.roll);
  v.up = cross(v.right, v.forward);
  v.tanHalf = tan(radians(params.fov) * 0.5);
  v.aspect = frameU.resolution.x / max(frameU.resolution.y, 1.0);
  return v;
}

fn rayAt(v: View, uv: vec2f) -> vec3f {
  let ndc = vec2f(uv.x * 2.0 - 1.0, 1.0 - uv.y * 2.0);
  return normalize(v.forward + v.right * ndc.x * v.tanHalf * v.aspect + v.up * ndc.y * v.tanHalf);
}

fn depthTexel(uv: vec2f) -> vec2i {
  let size = vec2f(textureDimensions(inputTexture1));
  return clamp(vec2i(uv * size), vec2i(0), vec2i(size) - vec2i(1));
}

// View-plane distance at uv, or a negative number where there is no surface.
fn viewDepth(uv: vec2f) -> f32 {
  let d = textureLoad(inputTexture1, depthTexel(uv), 0).r;
  return select(d * params.far, -1.0, d >= 0.9999 || d <= 0.0);
}

fn worldAt(v: View, uv: vec2f, z: f32) -> vec3f {
  let ray = rayAt(v, uv);
  return params.eye + ray * (z / max(dot(ray, v.forward), 1e-4));
}

// World point → (uv, view-plane distance); z ≤ 0 means behind the camera.
fn project(v: View, world: vec3f) -> vec3f {
  let rel = world - params.eye;
  let z = dot(rel, v.forward);
  let x = dot(rel, v.right) / (max(z, 1e-4) * v.tanHalf * v.aspect);
  let y = dot(rel, v.up) / (max(z, 1e-4) * v.tanHalf);
  return vec3f(x * 0.5 + 0.5, 0.5 - y * 0.5, z);
}

fn ignHash(pixel: vec2f) -> f32 {
  return fract(52.9829189 * fract(dot(pixel, vec2f(0.06711056, 0.00583715))));
}


fn projectWith(eye: vec3f, aim: vec3f, fov: f32, roll: f32, aspect: f32, world: vec3f) -> vec2f {
  let forward = normalize(aim - eye);
  let right = rolledRight(forward, roll);
  let up = cross(right, forward);
  let tanHalf = tan(radians(fov) * 0.5);
  let rel = world - eye;
  let z = max(dot(rel, forward), 1e-4);
  return vec2f(dot(rel, right) / (z * tanHalf * aspect) * 0.5 + 0.5, 0.5 - dot(rel, up) / (z * tanHalf) * 0.5);
}

fn historyAt(uv: vec2f) -> vec3f {
  let size = vec2f(textureDimensions(inputTexture2));
  let g = uv * size - 0.5;
  let b = vec2i(floor(g));
  let f = fract(g);
  let lim = vec2i(size) - vec2i(1);
  let h00 = textureLoad(inputTexture2, clamp(b, vec2i(0), lim), 0).rgb;
  let h10 = textureLoad(inputTexture2, clamp(b + vec2i(1, 0), vec2i(0), lim), 0).rgb;
  let h01 = textureLoad(inputTexture2, clamp(b + vec2i(0, 1), vec2i(0), lim), 0).rgb;
  let h11 = textureLoad(inputTexture2, clamp(b + vec2i(1, 1), vec2i(0), lim), 0).rgb;
  return mix(mix(h00, h10, f.x), mix(h01, h11, f.x), f.y);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let size = vec2f(textureDimensions(inputTexture));
  let px = vec2i(uv * size);
  let current = textureLoad(inputTexture, px, 0);
  if (params.reset > 0.5) { return current; }
  // The 3×3 neighbourhood's range (in a tone-compressed space, so a spark does not blow it open).
  var lo = vec3f(1e9);
  var hi = vec3f(-1e9);
  for (var y = -1; y <= 1; y = y + 1) {
    for (var x = -1; x <= 1; x = x + 1) {
      let c = textureLoad(inputTexture, clamp(px + vec2i(x, y), vec2i(0), vec2i(size) - vec2i(1)), 0).rgb;
      let t = c / (1.0 + c);
      lo = min(lo, t);
      hi = max(hi, t);
    }
  }
  let v = makeView();
  var z = viewDepth(uv);
  if (z < 0.0) { z = params.far * 0.5; }
  let previous = projectWith(params.prevEye, params.prevAim, params.prevFov, params.prevRoll, v.aspect, worldAt(v, uv, z));
  if (any(previous < vec2f(0.0)) || any(previous > vec2f(1.0))) { return current; }
  let h = historyAt(previous);
  let ht = clamp(h / (1.0 + h), lo, hi);
  let clamped = ht / max(vec3f(1.0) - ht, vec3f(1e-4));
  return vec4f(mix(clamped, current.rgb, params.blend), current.a);
}
